package io.github.jesterportfolio.hearth.survival.economy;

import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.survival.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.event.world.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import net.kyori.adventure.text.Component;

/** 읽기 전용 경제/공급망 조회와 근거리 상인 거래. 메뉴 입력에서 가격/잔액을 받지 않습니다. */
public final class NativeEconomyMenu implements Listener,AutoCloseable {
    private final JavaPlugin plugin;private final SurvivalEconomy economy;private final Map<String,Villager> npcs=new HashMap<>();private final Map<UUID,Object> loads=new HashMap<>();private final Map<String,EconomyReport.Definition> reports=new HashMap<>();private final Map<String,EconomySupply.Plan> supplies=new HashMap<>();private boolean closed;
    private final class Screen implements InventoryHolder{final Player player;final Object token;final String merchant;final Villager npc;final Inventory inventory;final Map<Integer,Runnable> actions=new HashMap<>();Screen(Player p,String title,String merchant){player=p;token=economy.token(p);this.merchant=merchant;npc=merchant==null?null:npcs.get(merchant);inventory=Bukkit.createInventory(this,54,Component.text(title));}public Inventory getInventory(){return inventory;}}
    public NativeEconomyMenu(JavaPlugin plugin,SurvivalEconomy economy){this.plugin=plugin;this.economy=economy;for(var merchant:economy.merchants.all()){var report=EconomyReport.parse(economy.properties,economy.content,merchant.shop());reports.put(merchant.id(),report);supplies.put(merchant.id(),EconomySupply.parse(economy.properties,economy.content,report));}Bukkit.getPluginManager().registerEvents(this,plugin);
        Objects.requireNonNull(plugin.getCommand("economy")).setExecutor((sender,command,label,args)->{if(sender instanceof Player p)home(p);return true;});Objects.requireNonNull(plugin.getCommand("balance")).setExecutor((sender,command,label,args)->{if(sender instanceof Player p&&economy.free(p)){var token=economy.token(p);economy.store.account(economy.context(p)).whenCompleteAsync((account,error)->{if(!economy.same(p,token))return;p.sendMessage(Component.text(error==null?"보유 화폐: "+account.balance():"잔액을 조회하지 못했습니다."));},economy.owner);}return true;});Objects.requireNonNull(plugin.getCommand("shop")).setExecutor((sender,command,label,args)->{if(sender instanceof Player p){if(args.length==1)catalog(p,args[0],0);else p.sendMessage(Component.text("상인을 우클릭하거나 /상점 <상인 ID>를 이용하세요."));}return true;});
    }
    private SurvivalWorld role(String id){return SurvivalWorld.id(economy.properties.getProperty("merchant."+id+".world","residence"));}
    public CompletionStage<Void> prepare(){var jobs=new ArrayList<CompletableFuture<?>>();for(var merchant:economy.merchants.all()){var world=economy.world(role(merchant.id()));var at=merchant.point();int x=((int)Math.floor(at.x()))>>4,z=((int)Math.floor(at.z()))>>4;if(!world.isChunkGenerated(x,z))return CompletableFuture.failedFuture(new IllegalStateException("NATIVE_MERCHANT_UNPREPARED_CHUNK"));jobs.add(world.getChunkAtAsync(x,z,false).thenAcceptAsync(chunk->{if(closed||chunk==null||!SurvivalWorlds.safe(new Location(world,at.x(),at.y(),at.z())))throw new IllegalStateException("NATIVE_MERCHANT_UNSAFE");spawn(merchant);},economy.owner));}return CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new));}
    private void spawn(EconomyMerchants.Merchant merchant){var existing=npcs.get(merchant.id());if(closed||existing!=null&&existing.isValid())return;var at=merchant.point();var world=economy.world(role(merchant.id()));if(!world.isChunkLoaded(((int)Math.floor(at.x()))>>4,((int)Math.floor(at.z()))>>4))return;var p=new Location(world,at.x(),at.y(),at.z());if(!SurvivalWorlds.safe(p))return;var npc=world.spawn(p,Villager.class,v->{v.setAI(false);v.setInvulnerable(true);v.setSilent(true);v.setCollidable(false);v.setPersistent(false);v.customName(Component.text(merchant.name()));v.setCustomNameVisible(true);});npcs.put(merchant.id(),npc);}
    public boolean near(Player p,String merchant){try{var definition=economy.merchants.get(merchant);var npc=npcs.get(merchant);var at=definition.point();return npc!=null&&npc.isValid()&&npc.getWorld()==economy.world(role(merchant))&&p.getWorld()==npc.getWorld()&&npc.getLocation().distanceSquared(new Location(npc.getWorld(),at.x(),at.y(),at.z()))<=.25&&p.getLocation().distanceSquared(npc.getLocation())<=25;}catch(RuntimeException error){return false;}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void npc(PlayerInteractEntityEvent e){if(e.getHand()!=EquipmentSlot.HAND)return;for(var row:npcs.entrySet())if(row.getValue()==e.getRightClicked()){e.setCancelled(true);catalog(e.getPlayer(),row.getKey(),0);return;}}
    @EventHandler public void chunkLoad(ChunkLoadEvent e){for(var m:economy.merchants.all())if(economy.world(role(m.id()))==e.getWorld()&&(((int)Math.floor(m.point().x()))>>4)==e.getChunk().getX()&&(((int)Math.floor(m.point().z()))>>4)==e.getChunk().getZ())spawn(m);}
    @EventHandler(ignoreCancelled=true) public void chunkUnload(ChunkUnloadEvent e){for(var row:List.copyOf(npcs.entrySet())){var npc=row.getValue();if(npc.getWorld()==e.getWorld()&&npc.getLocation().getBlockX()>>4==e.getChunk().getX()&&npc.getLocation().getBlockZ()>>4==e.getChunk().getZ()){npcs.remove(row.getKey(),npc);npc.remove();}}}
    private boolean active(Player p){return !closed&&economy.free(p)&&!economy.peers.busy(p.getUniqueId());}
    private boolean current(Screen s){return active(s.player)&&economy.same(s.player,s.token)&&s.player.getOpenInventory().getTopInventory()==s.inventory&&(s.merchant==null||s.npc!=null&&npcs.get(s.merchant)==s.npc&&near(s.player,s.merchant));}
    private void button(Screen s,int slot,Material material,String title,Runnable action,String... lore){var item=new ItemStack(material);item.editMeta(meta->{meta.displayName(Component.text(title));meta.lore(Arrays.stream(lore).map(Component::text).toList());});s.inventory.setItem(slot,item);if(action!=null)s.actions.put(slot,action);}
    private <T> void load(Player p,CompletionStage<T> job,String title,String merchant,BiConsumer<Screen,T> render){if(!active(p)||merchant!=null&&!near(p,merchant)){p.sendMessage(Component.text("거래·이동을 마치고 상인 가까이에서 다시 이용하세요."));return;}var selected=merchant==null?null:npcs.get(merchant);var token=economy.token(p);var origin=p.getOpenInventory().getTopInventory();var request=new Object();loads.put(p.getUniqueId(),request);job.whenCompleteAsync((value,error)->{if(closed||loads.get(p.getUniqueId())!=request||!active(p)||!economy.same(p,token)||p.getOpenInventory().getTopInventory()!=origin||merchant!=null&&(npcs.get(merchant)!=selected||!near(p,merchant)))return;loads.remove(p.getUniqueId(),request);if(error!=null){p.sendMessage(Component.text("경제 정보를 조회하지 못했습니다."));return;}try{var screen=new Screen(p,title,merchant);render.accept(screen,value);p.openInventory(screen.inventory);}catch(RuntimeException invalid){p.sendMessage(Component.text("경제 화면을 열지 못했습니다."));}},economy.owner);}
    public void home(Player p){if(!active(p))return;String id=economy.merchants.first().id();load(p,economy.store.account(economy.context(p)),"경제 · 잔액과 시장",null,(s,account)->{button(s,4,Material.EMERALD,"보유 화폐: "+account.balance(),null,"새 계정은 잔액 0으로 시작합니다.","채집한 일반 상품을 상인에게 판매할 수 있습니다.");button(s,20,Material.COMPASS,"지역 시장·생산·운송",()->report(p,id,reports.get(id).regions().getFirst().id(),"MARKET",0));button(s,22,Material.BOOK,"본인 거래 기록",()->history(p,Long.MAX_VALUE));button(s,24,Material.MAP,"상품 공급망·안내",()->supply(p,id,reports.get(id).goods().getFirst(),0));int slot=27;for(var merchant:economy.merchants.all()){if(slot>=45)break;String m=merchant.id();boolean near=near(p,m);button(s,slot++,Material.VILLAGER_SPAWN_EGG,merchant.name(),near?()->catalog(p,m,0):null,near?"상점 열기":"상인 가까이에서 이용하세요.","상인 ID: "+m);}});}
    public void catalog(Player p,String id,int page){if(!active(p)||!near(p,id))return;var merchant=economy.merchants.get(id);load(p,economy.store.offers(economy.context(p),merchant.shop().region(),merchant.shop().goods()),merchant.name(),id,(s,offers)->{var index=merchant.shop().index(offers);int slot=0;for(String good:merchant.shop().page(page)){var offer=index.get(good);button(s,slot++,Material.valueOf(economy.content.goods().get(good).material()),merchant.shop().name(good),()->product(p,id,offer,1),"재고: "+offer.market().stock(),"1개 구매: "+(offer.market().stock()>0?EconomyEngine.quote(economy.content,good,offer.market(),1,true):"품절"),"1개 판매: "+EconomyEngine.quote(economy.content,good,offer.market(),1,false),"잔액: "+offer.balance());}if(page>0)button(s,45,Material.ARROW,"이전 상품",()->catalog(p,id,page-1));if((page+1)*45<merchant.shop().goods().size())button(s,53,Material.ARROW,"다음 상품",()->catalog(p,id,page+1));button(s,48,Material.COMPASS,"시장 상황",()->report(p,id,merchant.shop().region(),"MARKET",0));button(s,49,Material.BOOK,"내 거래 기록",()->history(p,Long.MAX_VALUE));button(s,50,Material.CLOCK,"새로고침",()->catalog(p,id,page));});}
    private void product(Player p,String id,EconomyStore.Offer offer,int quantity){economy.merchants.get(id).require(offer);if(!active(p)||!near(p,id))return;var screen=new Screen(p,economy.merchants.get(id).shop().name(offer.key().good())+" · 수량",id);fillProduct(screen,p,id,offer,quantity);p.openInventory(screen.inventory);}
    private void fillProduct(Screen screen,Player p,String id,EconomyStore.Offer offer,int quantity){var merchant=economy.merchants.get(id);merchant.require(offer);var capacity=economy.items.capacity(economy.capture(p),offer.key().good());button(screen,4,Material.valueOf(economy.content.goods().get(offer.key().good()).material()),merchant.shop().name(offer.key().good()),null,"수량: "+quantity,"잔액: "+offer.balance(),"재고: "+offer.market().stock());for(boolean buy:List.of(true,false)){var quote=EconomyQuote.view(economy.content,offer,capacity,quantity,buy);button(screen,buy?10:28,quote.available()?Material.EMERALD:Material.GRAY_DYE,(buy?"구매":"판매")+" 견적",quote.available()?()->confirm(p,id,offer,quantity,buy):null,"총액: "+quote.total(),quote.guidance().replace("개발 화폐","화폐"));}int slot=19;for(int delta:new int[]{-64,-8,-1,1,8,64}){int n=EconomyQuote.adjust(quantity,delta);button(screen,slot++,Material.PAPER,(delta>0?"+":"")+delta,()->product(p,id,offer,n));}button(screen,45,Material.ARROW,"상품 목록",()->catalog(p,id,0));button(screen,50,Material.CLOCK,"최신 견적",()->load(p,economy.store.offer(economy.context(p),offer.key()),"최신 시세",id,(s,fresh)->fillProduct(s,p,id,fresh,quantity)));}
    private void confirm(Player p,String id,EconomyStore.Offer offer,int quantity,boolean buy){if(!active(p)||!near(p,id))return;var quote=EconomyQuote.view(economy.content,offer,economy.items.capacity(economy.capture(p),offer.key().good()),quantity,buy);var s=new Screen(p,"거래 최종 확인",id);button(s,13,Material.PAPER,(buy?"구매":"판매")+" · "+economy.merchants.get(id).shop().name(offer.key().good()),null,"수량: "+quantity,"총액: "+quote.total(),"잔액: "+quote.balance()+" → "+quote.projectedBalance(),quote.guidance().replace("개발 화폐","화폐"));var request=UUID.randomUUID();button(s,31,quote.available()?Material.LIME_DYE:Material.BARRIER,"거래 확정",quote.available()?()->trade(p,id,offer,quantity,buy,request):null,"가격·재고가 바뀌면 거래하지 않습니다.");button(s,45,Material.ARROW,"수량 선택",()->product(p,id,offer,quantity));p.openInventory(s.inventory);}
    private void trade(Player p,String id,EconomyStore.Offer offer,int quantity,boolean buy,UUID request){if(!active(p)||!near(p,id)||!p.getItemOnCursor().isEmpty())return;var token=economy.token(p);var context=economy.context(p);var port=economy.port(p);p.closeInventory();economy.transactions.begin(request,"SHOP",List.of(port),economy.ledger.shop(context,offer,quantity,buy,request,EconomyStore.Probe.NONE)).whenCompleteAsync((result,error)->{if(!economy.same(p,token))return;if(error!=null){p.sendMessage(Component.text(io.github.jesterportfolio.hearth.inventory.InventorySaveSession.code(error).equals("ECON_REQUEST_BUSY")?"현재 거래 준비 상태와 커서 아이템을 확인하세요.":PaperEconomy.tradeFailure(error).replace("개발 화폐","화폐")));return;}var receipt=(EconomyStore.Receipt)result.receipt();p.sendMessage(Component.text("거래 금액: "+receipt.total()+" · 잔액: "+receipt.account().balance()));},economy.owner);}
    private void history(Player p,long cursor){if(!active(p))return;load(p,economy.store.history(economy.context(p),cursor,20),"내 거래 기록",null,(s,rows)->{int slot=0;for(var row:rows)button(s,slot++,Material.PAPER,(row.buy()?"구매 · ":"판매 · ")+economy.properties.getProperty("good."+row.key().good()+".name",row.key().good()),null,"수량: "+row.quantity(),"금액: "+row.total(),"지역: "+row.key().region());button(s,45,Material.ARROW,"경제 홈",()->home(p));if(rows.size()==20)button(s,53,Material.ARROW,"이전 기록",()->history(p,rows.getLast().inventoryRevision()));});}
    private void report(Player p,String id,String region,String kind,int page){if(!active(p))return;load(p,economy.store.report(economy.context(p),reports.get(id),region),"시장 · "+region,null,(s,view)->{var rows=new ArrayList<String[]>();switch(kind){case "MARKET"->{for(var r:view.markets()){var lore=new ArrayList<String>(List.of("재고: "+r.stock(),"구매: "+r.ask()+" / 판매: "+r.bid(),"수요: "+r.demand()));lore.addAll(EconomySupply.flowLines(r.flow()));rows.add(join(r.name(),lore));}}case "FACILITIES"->{for(var r:view.facilities())rows.add(join(r.name(),List.of("생산 상품: "+r.good(),"생산량: "+r.possible()+" / 용량: "+r.capacity(),r.restriction(),"투입: "+r.inputs())));}case "ROUTES"->{for(var r:view.routes())rows.add(join(r.name(),List.of(r.from()+" → "+r.to(),"운송 중: "+r.inTransit(),"다음 도착: "+r.nextArrival()+" Tick",r.blocked()?"운송 차단":"운송 중")));}case "EVENTS"->{for(var r:view.events())rows.add(join(r.name(),List.of(r.description(),"시작까지: "+r.startsIn()+" / 남은 Tick: "+r.remaining())));}default->throw new IllegalArgumentException();}int slot=0;for(var row:EconomyReport.page(rows,page))button(s,slot++,Material.PAPER,row[0],null,Arrays.copyOfRange(row,1,row.length));if(page>0)button(s,45,Material.ARROW,"이전",()->report(p,id,region,kind,page-1));button(s,46,Material.EMERALD,"경제 홈",()->home(p));int nav=47;for(String mode:List.of("MARKET","FACILITIES","ROUTES","EVENTS")){String title=switch(mode){case "MARKET"->"시장";case "FACILITIES"->"생산·제련";case "ROUTES"->"운송";default->"경제 사건";};button(s,nav++,Material.BOOK,title,()->report(p,id,region,mode,0));}int ri=view.regions().stream().map(EconomyReport.Region::id).toList().indexOf(region);String next=view.regions().get((ri+1)%view.regions().size()).id();button(s,51,Material.COMPASS,"다음 지역",()->report(p,id,next,kind,0));if((page+1)*45<rows.size())button(s,53,Material.ARROW,"다음",()->report(p,id,region,kind,page+1));});}
    private static String[] join(String title,List<String> lore){var row=new ArrayList<String>();row.add(title);row.addAll(lore);return row.toArray(String[]::new);}
    private void supply(Player p,String id,String good,int page){if(!active(p))return;load(p,economy.store.supply(economy.context(p),reports.get(id),economy.merchants,supplies.get(id),good),"상품 공급망·안내",null,(s,view)->{var rows=new ArrayList<String[]>();for(var n:view.nodes())rows.add(join(n.title(),n.lines()));for(var step:view.steps())rows.add(join(step.title(),List.of(step.text())));int slot=0;for(var row:EconomyReport.page(rows,page))button(s,slot++,Material.MAP,row[0],null,Arrays.copyOfRange(row,1,row.length));button(s,45,Material.ARROW,"경제 홈",()->home(p));int i=view.goods().stream().map(EconomySupply.Good::id).toList().indexOf(good);String next=view.goods().get((i+1)%view.goods().size()).id();button(s,49,Material.PAPER,"다음 상품",()->supply(p,id,next,0));if(page>0)button(s,48,Material.ARROW,"이전",()->supply(p,id,good,page-1));if((page+1)*45<rows.size())button(s,53,Material.ARROW,"다음",()->supply(p,id,good,page+1));});}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof NativeEconomyMenu.Screen s))return;boolean denied=e.isCancelled();e.setCancelled(true);if(!NativeMenuRules.allow(e.getWhoClicked()==s.player&&current(s),denied,e.getClickedInventory()==s.inventory,s.player.getItemOnCursor().isEmpty(),e.getClick().name(),false))return;var action=s.actions.get(e.getSlot());if(action!=null)Bukkit.getScheduler().runTask(plugin,()->{if(current(s))action.run();});}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof NativeEconomyMenu.Screen)e.setCancelled(true);}
    public void invalidate(UUID player){loads.remove(player);}
    public int liveMerchants(){return (int)npcs.values().stream().filter(Entity::isValid).count();}
    @Override public void close(){closed=true;HandlerList.unregisterAll(this);for(var npc:npcs.values())npc.remove();npcs.clear();loads.clear();}
}
